ruleContent.content:
@js:
(() => {
    let html = String(result || "");
    if (!html) return "";

    /* ========== 第2段：通用字段提取（顺序无关 / 带不带引号都行） ========== */
    let pick = (key) => {
        let m = html.match(new RegExp('"' + key + '"\\s*:\\s*"([^"]*)"'));
        if (m) return m[1].trim();
        m = html.match(new RegExp('"' + key + '"\\s*:\\s*([^,\\s}]+)'));
        return m ? m[1].trim() : "";
    };

    let url     = pick("url");
    let mobile  = pick("mobile") || "1";
    let isk     = pick("isk")    || "1";
    let novel   = pick("novel");
    let chapter = pick("chapter");
    let t       = pick("t");
    let n       = pick("n");
    let sign    = pick("sign");

    /* ========== 第2段：保留参数日志 ========== */
    let paramsObj = { url, mobile, isk, novel, chapter, t, n, sign };
    java.log(
        Object.keys(paramsObj).map(k => k + "=" + paramsObj[k] + ",\n").join("")
    );

    if (!url || !sign || !novel || !chapter) {
        java.log("参数提取不完整");
        return "";
    }

    /* ========== 第1段：请求体用 encodeURIComponent 编码 ========== */
    let body =
        "url=" + encodeURIComponent(url) +
        "&mobile=" + encodeURIComponent(mobile) +
        "&isk=" + encodeURIComponent(isk) +
        "&novel=" + encodeURIComponent(novel) +
        "&chapter=" + encodeURIComponent(chapter) +
        "&t=" + encodeURIComponent(t) +
        "&n=" + encodeURIComponent(n) +
        "&sign=" + encodeURIComponent(sign);

    java.log("body: " + body);

    let siteurl = "https://bcshuku.com";
    let referer = (typeof baseUrl === "string" && baseUrl)
        ? baseUrl
        : siteurl + "/novel/" + novel + "/chapter" + chapter + ".html";

    /* ========== 第1段：请求头 / java.post ========== */
    let response = java.post(siteurl + "/conapi.php", body, {
        'User-Agent': 'Mozilla/5.0 (Linux; U; Android 10; zh-CN; MI 9 Build/QKQ1.190828.002) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/100.0.4896.58 Quark/10.5.1.1026 Mobile Safari/537.36',
        'Accept': 'application/json, text/javascript, */*; q=0.01',
        'x-requested-with': 'XMLHttpRequest',
        'content-type': 'application/x-www-form-urlencoded; charset=UTF-8',
        'origin': 'https://www.bcshuku.com',
        'sec-fetch-site': 'same-origin',
        'sec-fetch-mode': 'cors',
        'sec-fetch-dest': 'empty',
        'accept-language': 'zh-CN,zh;q=0.9,en-US;q=0.8,en;q=0.7',
        'referer': referer,
    });

    /* ========== 第1段：响应处理 ========== */
    if (response && response.body()) {
        try {
            let data = JSON.parse(response.body());

            // 补上第2段的 success 判断，避免把失败响应当正文
            if (!data || data.success === false || data.success === 0 ||
                data.success === "0" || !data.content) {
                java.log("接口失败：" + response.body());
                return "";
            }

            let content = String(data.content);
            java.log(content);

            // 第2段：内容清洗
            return content
                .replace(/<br\s*\/?>/gi, "\n")
                .replace(/&nbsp;/g, " ")
                .replace(/&lt;/g, "<")
                .replace(/&gt;/g, ">")
                .replace(/&amp;/g, "&");
        } catch (e) {
            java.log("运行异常: " + e.message);
            return "";
        }
    } else {
        java.log("响应体为空");
        return "";
    }
})()

