		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
push("全部🌊分类",null,1,1)
push("🌊全本🌊",`http://m.cxzz958.com/wanben/{{page}}.html`,1,1)
	arList=["玄幻小说","仙侠小说","都市小说","军史小说","网游小说","科幻小说","恐怖小说","其它小说"]
	arList.map((tag,index)=>{
		url=`/fenlei/${index+1}/{{page}}.html`;
		push(tag, url, 1, 0.25);
		});
//java.log(JSON.stringify(sort))
JSON.stringify(sort)

